describe('Confirmation Modal for Deleting a Record', () => {
    beforeEach(() => {
        cy.visit('/records'); // Adjust the URL to your application's records page
    });

    it('should display confirmation modal when delete button is clicked', () => {
        cy.get('.delete-button').first().click(); // Adjust the selector to your delete button
        cy.get('.confirmation-modal').should('be.visible'); // Adjust the selector to your modal
        cy.get('.confirmation-modal .modal-title').should('contain', 'Confirm Deletion'); // Adjust the selector to your modal title
    });

    it('should not delete the record if the user cancels the deletion', () => {
        cy.get('.delete-button').first().click(); // Open the confirmation modal
        cy.get('.confirmation-modal .cancel-button').click(); // Adjust the selector to your cancel button
        cy.get('.confirmation-modal').should('not.exist'); // Ensure the modal is closed
        cy.get('.record-list').should('contain', 'Record Name'); // Adjust the selector and text to verify the record still exists
    });
});
